"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a field value, treating missing fields as the legacy empty string."""
    if row is None:
        return ""
    return row.get(column, "")


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion for empty values."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _length(value: Any) -> int:
    """Apply legacy LEN behavior, where missing/null values have length zero."""
    if value is None or value == "":
        return 0
    return len(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # The migrated rules do not reference TODAY().

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        acct_typ = _value(record, "ACCT_TYP")
        if not (
            acct_typ == "C"
            or acct_typ == "P"
            or acct_typ == "R"
            or acct_typ == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        ann_rev = _value(record, "ANN_REV")
        if _numeric(0 if ann_rev is None or ann_rev == "" else ann_rev) < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        old_cred_hold = _value(old, "CRED_HOLD")
        if (
            old_cred_hold == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _numeric(_value(record, "CRED_LIMIT")) <= 0
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
